-- IMP-CMP-013: evidence-derived CASA command-centre status across operational domains.
create or replace function public.ftf_read_casa_compliance_overview(p_organisation_id uuid,p_evaluated_at timestamptz default now())returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
with reoc as(select*from public.organisation_compliance_instruments where organisation_id=p_organisation_id and instrument_type='REOC'and archived_at is null order by created_at desc limit 1),manual as(select v.*from public.controlled_document_versions v join public.controlled_documents d on d.organisation_id=v.organisation_id and d.id=v.document_id where v.organisation_id=p_organisation_id and d.document_type='OPERATIONS_MANUAL'order by v.version_number desc limit 1),active_people as(select*from public.personnel where organisation_id=p_organisation_id and is_active and archived_at is null),active_aircraft as(select*from public.aircraft where organisation_id=p_organisation_id and archived_at is null)
select jsonb_build_object('evaluatedAt',p_evaluated_at,'reoc',(select to_jsonb(x)||jsonb_build_object('daysRemaining',x.expiry_date-current_date)from reoc x),'operationsManual',(select to_jsonb(x)||jsonb_build_object('outstandingAcknowledgements',(select count(*)from active_people p where not exists(select 1 from public.controlled_document_acknowledgements a where a.organisation_id=p_organisation_id and a.document_version_id=x.id and a.personnel_id=p.id)))from manual x),'personnel',jsonb_build_object('missingCertificates',(select count(*)from active_people p where exists(select 1 from public.personnel_operational_roles r where r.organisation_id=p_organisation_id and r.personnel_id=p.id and r.role_code in('pilot','pilot_in_command'))and not exists(select 1 from public.personnel_credentials c where c.organisation_id=p_organisation_id and c.personnel_id=p.id and c.credential_type='RePL'and c.credential_state='CURRENT')),'unverifiedCertificates',(select count(*)from public.personnel_credentials c join active_people p on p.id=c.personnel_id where c.organisation_id=p_organisation_id and c.verification_state<>'verified')),'aircraft',jsonb_build_object('registrationWarnings',(select count(*)from active_aircraft where nullif(registration,'')is null),'technicalWarnings',(select count(*)from active_aircraft where not mission_ready or serviceability_state<>'serviceable'or next_inspection_due<current_date or next_major_service_due<current_date or insurance_expiry_date<current_date),'missingEvidence',(select count(*)from active_aircraft where jsonb_array_length(documentation->'certificates')=0)),'training',jsonb_build_object('outstanding',(select count(*)from public.compliance_training_records where organisation_id=p_organisation_id and outcome not in('COMPETENT','COMPLETED','PASSED'))),'checklists',jsonb_build_object('missing',(select count(*)from public.checklist_templates t where t.organisation_id=p_organisation_id and t.archived_at is null and not exists(select 1 from public.checklist_template_versions v where v.organisation_id=t.organisation_id and v.template_id=t.id and v.status='PUBLISHED')),'reviewsDue',(select count(*)from public.checklist_template_versions where organisation_id=p_organisation_id and status='PUBLISHED'and review_due_date<=current_date)),'warnings',jsonb_build_object('renewalsOverdue',(select count(*)from public.compliance_renewal_actions where organisation_id=p_organisation_id and status in('OPEN','IN_PROGRESS')and due_date<current_date),'legalHolds',(select count(*)from public.compliance_legal_holds where organisation_id=p_organisation_id and released_at is null),'retainedRecords',(select count(*)from public.compliance_legal_holds where organisation_id=p_organisation_id),'missingEvidence',(select count(*)from public.organisation_compliance_instruments i where i.organisation_id=p_organisation_id and i.archived_at is null and not exists(select 1 from public.compliance_instrument_evidence e where e.organisation_id=i.organisation_id and e.instrument_id=i.id))))$$;
revoke all on function public.ftf_read_casa_compliance_overview(uuid,timestamptz)from public,anon,authenticated;grant execute on function public.ftf_read_casa_compliance_overview(uuid,timestamptz)to service_role;
